#!/usr/bin/env bash\nset -euo pipefail\n\n# PostgreSQL's official image executes *.sh init scripts with the database\n# environment available. Keep application runtime credentials out of source\n# control while still creating the required databases/role deterministically.\n\npsql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" <<SQL\nCREATE DATABASE n8n;\nCREATE DATABASE listmonk_internal;\n\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'fadereach_runtime') THEN\n        CREATE ROLE fadereach_runtime LOGIN PASSWORD '${POSTGRES_RUNTIME_PASSWORD}';\n    ELSE\n        ALTER ROLE fadereach_runtime LOGIN PASSWORD '${POSTGRES_RUNTIME_PASSWORD}';\n    END IF;\nEND\n$$;\n\nGRANT CONNECT ON DATABASE "$POSTGRES_DB" TO fadereach_runtime;\nSQL\n